// TypeScript definitions for @grafeo-db/wasm
// These are auto-generated by wasm-pack during build.
// The declarations below are a reference for the expected API.

/**
 * Initialize the WASM module. Must be called before using any other API.
 */
export default function init(): Promise<void>;

/** What a write statement changed (all zero for a read). */
export interface WriteCounters {
  nodesCreated: number;
  nodesDeleted: number;
  edgesCreated: number;
  edgesDeleted: number;
  propertiesSet: number;
  labelsAdded: number;
  labelsRemoved: number;
}

/**
 * Any object of the RDF/JS data model that a term parameter or property
 * takes: the terms of these results, and the terms of other libraries
 * (N3.js, rdf-data-factory), read by `termType` and `value`, and for a
 * literal `language` and the `value` of `datatype`.
 */
export interface RdfTermLike {
  termType: string;
  value: string;
  language?: string;
  datatype?: { value: string };
}

/** An IRI in the RDF/JS data model. */
export interface NamedNode {
  termType: 'NamedNode';
  value: string;
  /** True when `other` is a term with the same `termType` and `value`. */
  equals(other: RdfTermLike | null | undefined): boolean;
}

/** A blank node in the RDF/JS data model: `value` is its label, without `_:`. */
export interface BlankNode {
  termType: 'BlankNode';
  value: string;
  /** True when `other` is a term with the same `termType` and `value`. */
  equals(other: RdfTermLike | null | undefined): boolean;
}

/**
 * A literal in the RDF/JS data model: `language` is the tag in lowercase,
 * `''` when it has none, and `datatype` is `rdf:langString` for a tagged
 * literal, `xsd:string` for a simple one.
 */
export interface Literal {
  termType: 'Literal';
  value: string;
  language: string;
  datatype: NamedNode;
  /**
   * True when `other` is a literal with the same `value`, the same language
   * (tags compare without case) and an equal datatype.
   */
  equals(other: RdfTermLike | null | undefined): boolean;
}

/** An RDF term, as SPARQL results hold them and parameters take them. */
export type RdfTerm = NamedNode | BlankNode | Literal;

/** The result of the `executeRaw*` methods. */
export interface RawResult {
  columns: string[];
  rows: unknown[][];
  /**
   * What the result holds: `'rows'` (SPARQL SELECT and updates, and every
   * other language), `'boolean'` (SPARQL ASK, see `boolean`) or `'graph'`
   * (SPARQL CONSTRUCT and DESCRIBE: `subject`, `predicate` and `object`
   * columns of RDF terms).
   */
  kind: 'rows' | 'boolean' | 'graph';
  /** The answer of a SPARQL ASK; absent for every other result. */
  boolean?: boolean;
  executionTimeMs?: number;
  counters: WriteCounters;
}

/** What an upsert did with its rows. */
export interface UpsertSummary {
  created: number;
  updated: number;
  skipped: number;
  skippedRows: number[];
}

/** The options of `new Database(options)`. */
export interface DatabaseOptions {
  /** `'off'` (the default), `'forever'` or how far back the history reaches, in milliseconds. */
  historyRetention?: 'off' | 'forever' | number;
}

/**
 * A point in time: a `bigint` is an epoch, a `Date` a time, `{ ago }` that many milliseconds
 * before now. A plain `number` throws a `TypeError`: it could be either an epoch or a time.
 */
export type TimePoint = bigint | Date | { ago: number };

/**
 * A read-only view of the database as it was at an earlier epoch, from `db.asOf(point)`. A query
 * that writes throws; `close()` releases the history it keeps, and later calls throw.
 */
export class AsOfView {
  private constructor();
  /** The epoch the view reads at. */
  readonly epoch: bigint;
  execute(query: string): Record<string, unknown>[];
  executeWithParams(query: string, params: Record<string, unknown>): Record<string, unknown>[];
  executeRaw(query: string): RawResult;
  close(): void;
  free(): void;
}

/**
 * A handle on one named graph, from `db.graph(name)`. Each call runs on its own, so a call
 * throws while the database has a transaction open, once the graph is dropped, and after close.
 */
export class GraphHandle {
  readonly name: string;
  execute(query: string): Record<string, unknown>[];
  executeWithParams(query: string, params: Record<string, unknown>): Record<string, unknown>[];
  executeWithLanguage(query: string, language: string): Record<string, unknown>[];
  executeWithLanguageAndParams(
    query: string,
    language: string,
    params: Record<string, unknown>,
  ): Record<string, unknown>[];
  executeRaw(query: string): RawResult;
  executeRawWithParams(query: string, params: Record<string, unknown>): RawResult;
  executeRawWithLanguage(query: string, language: string): RawResult;
  executeRawWithLanguageAndParams(query: string, language: string, params: Record<string, unknown>): RawResult;
  batchCreateNodesWithProps(labels: string | string[], rows: Record<string, unknown>[]): number[];
  batchCreateEdges(
    edges: { src: number; dst: number; type: string; properties?: Record<string, unknown> }[],
  ): number[];
  upsertNodes(
    labels: string | string[],
    rows: Record<string, unknown>[],
    options?: { key?: string; replace?: boolean },
  ): UpsertSummary;
  upsertEdges(edgeType: string, rows: Record<string, unknown>[], options?: Record<string, unknown>): UpsertSummary;
  free(): void;
}

/**
 * A Grafeo graph database instance running in WebAssembly.
 *
 * All data is held in memory within the WASM heap. For persistence,
 * use `exportSnapshot()` / `importSnapshot()` with IndexedDB or
 * the higher-level `@grafeo-db/web` package.
 */
export class Database {
  /**
   * Creates a new in-memory database. `historyRetention` sets how much history it keeps for
   * time-travel reads (`asOf`): `'off'` (the default), `'forever'` or a number of milliseconds.
   */
  constructor(options?: DatabaseOptions | null);

  /** The epoch of the last commit. */
  currentEpoch(): bigint;

  /**
   * The epoch a point in time reads at: the epoch itself (the current one for a later one), or
   * the last commit at or before a time. Throws for a point before the history the database keeps.
   */
  epochAsOf(point: TimePoint): bigint;

  /** A read-only view of the database at a point in time; it keeps its history until `close()`. */
  asOf(point: TimePoint): AsOfView;

  /** Runs one GQL query at a point in time; rows as objects, as `execute`. */
  executeAsOf(query: string, point: TimePoint, params?: Record<string, unknown> | null): Record<string, unknown>[];

  /**
   * Executes a GQL query and returns results as an array of objects.
   *
   * Each row becomes a JavaScript object with column names as keys.
   *
   * @example
   * ```js
   * const results = db.execute("MATCH (p:Person) RETURN p.name, p.age");
   * // [{name: "Alix", age: 30}, {name: "Gus", age: 25}]
   * ```
   */
  execute(query: string): Record<string, unknown>[];

  /**
   * Executes a GQL query and returns raw columns, rows, and metadata.
   *
   * @returns `{ columns: string[], rows: unknown[][], executionTimeMs?: number, counters }`
   */
  executeRaw(query: string): RawResult;

  /**
   * Creates one node per row in one transaction; the node IDs in row order. This, the edge
   * batch, the upserts and `graph()` need the direct-api feature (lpg and full builds).
   */
  batchCreateNodesWithProps(labels: string | string[], rows: Record<string, unknown>[]): number[];

  /** Creates the edges in one transaction; the edge IDs in input order. */
  batchCreateEdges(
    edges: { src: number; dst: number; type: string; properties?: Record<string, unknown> }[],
  ): number[];

  /** Creates or updates nodes by a key property, in one statement. */
  upsertNodes(
    labels: string | string[],
    rows: Record<string, unknown>[],
    options?: { key?: string; replace?: boolean },
  ): UpsertSummary;

  /** Creates or updates edges between existing nodes by a key property, in one statement. */
  upsertEdges(
    edgeType: string,
    rows: Record<string, unknown>[],
    options?: {
      key?: string;
      endpointKey?: string;
      endpointLabels?: string[];
      srcField?: string;
      dstField?: string;
      replace?: boolean;
    },
  ): UpsertSummary;

  /** Searches several query vectors at once (requires the vector-index feature). */
  batchVectorSearch(
    label: string,
    property: string,
    queries: number[][],
    k: number,
    options?: { ef?: number; filters?: Record<string, unknown> },
  ): { id: number; distance: number }[][];

  /** A handle on a named graph, to work in it without switching the current graph. */
  graph(name: string): GraphHandle;

  /**
   * A node's edges without a query, as `[neighborId, edgeId]` pairs; `"both"` lists a
   * self-loop once. Reads through the open transaction when there is one.
   */
  getNodeEdges(
    id: number,
    options?: { direction?: "out" | "in" | "both"; edgeTypes?: string[] },
  ): [number, number][];

  /**
   * Deletes a node and all its incident edges in one operation. Uses the active
   * transaction, if any; rollback restores the node and edges. Returns false if
   * the node is absent. The ID must be a nonnegative safe integer.
   */
  detachDeleteNode(id: number): boolean;

  /** Returns the number of nodes in the database. */
  nodeCount(): number;

  /** Returns the number of edges in the database. */
  edgeCount(): number;

  /**
   * Executes a query using a specific query language.
   *
   * Supported languages: `"gql"`, `"cypher"`, `"sparql"`, `"gremlin"`, `"graphql"`.
   * Languages require their corresponding feature flag to be enabled at build time.
   *
   * @example
   * ```js
   * const results = db.executeWithLanguage("MATCH (p:Person) RETURN p.name", "cypher");
   * ```
   */
  executeWithLanguage(
    query: string,
    language: "gql" | "cypher" | "sparql" | "gremlin" | "graphql",
  ): Record<string, unknown>[];

  /**
   * Exports the database to a binary snapshot.
   *
   * Returns a `Uint8Array` that can be stored in IndexedDB, localStorage,
   * or sent over the network. Restore with `Database.importSnapshot()`.
   *
   * @example
   * ```js
   * const bytes = db.exportSnapshot();
   * ```
   */
  exportSnapshot(): Uint8Array;

  /**
   * Creates a database from a binary snapshot.
   *
   * @param data - Bytes previously produced by `exportSnapshot()`.
   *
   * @example
   * ```js
   * const db = Database.importSnapshot(bytes);
   * ```
   */
  static importSnapshot(data: Uint8Array): Database;

  /**
   * Returns schema information: the labels, edge types and property keys
   * in use, each sorted by name, with each label's and edge type's
   * properties (the types of their values) and the labels each edge type
   * connects. It reads the whole graph.
   *
   * @example
   * ```js
   * const schema = db.schema();
   * // { mode: "lpg",
   * //   labels: [{ name: "Person", count: 5, properties: [{ name: "name", types: ["STRING"] }] }],
   * //   edge_types: [{ name: "KNOWS", count: 3, properties: [],
   * //                  endpoints: [{ source: "Person", target: "Person", count: 3 }] }],
   * //   property_keys: ["name"] }
   * ```
   */
  schema():
    | {
        mode: "lpg";
        labels: Array<{
          name: string;
          count: number;
          properties: Array<{ name: string; types: string[] }>;
        }>;
        edge_types: Array<{
          name: string;
          count: number;
          properties: Array<{ name: string; types: string[] }>;
          endpoints: Array<{ source: string; target: string; count: number }>;
        }>;
        property_keys: string[];
      }
    | {
        mode: "rdf";
        predicates: Array<{ iri: string; count: number }>;
        named_graphs: string[];
        subject_count: number;
        object_count: number;
      };

  /**
   * Batch-imports LPG (Labeled Property Graph) data from a structured object.
   *
   * Nodes are created first, then edges. Edge `source`/`target` fields are
   * zero-based indexes into the `nodes` array.
   *
   * @example
   * ```js
   * const result = db.importLpg({
   *   nodes: [
   *     { labels: ["Person"], properties: { name: "Alix", age: 30 } },
   *     { labels: ["Person"], properties: { name: "Gus", age: 25 } },
   *   ],
   *   edges: [
   *     { source: 0, target: 1, type: "KNOWS", properties: { since: 2020 } }
   *   ]
   * });
   * // { nodes: 2, edges: 1 }
   * ```
   */
  importLpg(data: {
    nodes: Array<{
      labels: string[];
      properties?: Record<string, unknown>;
    }>;
    edges?: Array<{
      source: number;
      target: number;
      type: string;
      properties?: Record<string, unknown>;
    }>;
  }): { nodes: number; edges: number };

  /**
   * Batch-imports RDF triples from a structured object.
   *
   * Subjects and predicates are IRI strings (or blank nodes prefixed `_:`).
   * Objects can be a plain string (IRI) or a structured literal.
   *
   * Requires the `rdf` feature flag.
   *
   * @example
   * ```js
   * const result = db.importRdf({
   *   triples: [
   *     { subject: "http://example.org/Alix", predicate: "http://www.w3.org/1999/02/22-rdf-syntax-ns#type", object: "http://example.org/Person" },
   *     { subject: "http://example.org/Alix", predicate: "http://example.org/name", object: { value: "Alix" } },
   *     { subject: "http://example.org/Alix", predicate: "http://example.org/age", object: { value: "30", datatype: "http://www.w3.org/2001/XMLSchema#integer" } },
   *   ]
   * });
   * // { triples: 3 }
   * ```
   */
  importRdf(data: {
    triples: Array<{
      subject: string;
      predicate: string;
      object:
        | string
        | { value: string; datatype?: string; language?: string };
    }>;
  }): { triples: number };

  /** Returns the Grafeo version. */
  static version(): string;

  /** Frees the database from WASM memory. */
  free(): void;
}
